package common

import("bytes";"encoding/json";"fmt";"net/http")
type InstagramAdapter struct{Token,AccountID string;Client *http.Client}
func(a InstagramAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){event:=payload;if entries,ok:=payload["entry"].([]any);ok&&len(entries)>0{entry,_:=entries[0].(map[string]any);messaging,_:=entry["messaging"].([]any);if len(messaging)>0{event,_=messaging[0].(map[string]any)}};message,_:=event["message"].(map[string]any);sender,_:=event["sender"].(map[string]any);user,_:=sender["id"].(string);if user==""{return InboundEvent{},fmt.Errorf("Instagram event has no sender")};result:=InboundEvent{Platform:"instagram",UserID:user,ContentType:"text"};if text,ok:=message["text"].(string);ok{result.Text=text;return result,nil};attachments,_:=message["attachments"].([]any);if len(attachments)==0{return InboundEvent{},fmt.Errorf("Instagram event has no supported message")};attachment,_:=attachments[0].(map[string]any);result.ContentType=fmt.Sprint(attachment["type"]);if result.ContentType!="image"&&result.ContentType!="audio"&&result.ContentType!="video"{result.ContentType="file"};if p,ok:=attachment["payload"].(map[string]any);ok{result.MediaURL,_=p["url"].(string)};return result,nil}
func(a InstagramAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{body:=map[string]any{"recipient":map[string]string{"id":event.UserID}};if message.Type=="text"{body["message"]=map[string]string{"text":message.Text}}else{if message.MediaURL==""{return fmt.Errorf("Instagram media reply requires URL")};body["message"]=map[string]any{"attachment":map[string]any{"type":message.Type,"payload":map[string]string{"url":message.MediaURL}}}};data,_:=json.Marshal(body);req,_:=http.NewRequest(http.MethodPost,"https://graph.facebook.com/v20.0/"+a.AccountID+"/messages",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Instagram API returned %s",resp.Status)}};return nil}
